<template>
<div class="min-h-screen flex bg-slate-50 text-slate-800">
 <aside class="hidden lg:flex w-64 shrink-0 bg-teal-950 text-white p-6 flex-col"><div class="text-xl font-bold">JotnoHealthcare</div><p class="text-xs text-teal-200 mt-1">{{roleLabel}} workspace</p><nav class="mt-9 space-y-2"><button v-for="x in sections" :key="x" @click="section=x" class="w-full text-left rounded-xl px-4 py-3 text-sm" :class="section===x?'bg-white/15':'hover:bg-white/10'">{{x}}</button></nav><div class="mt-auto text-xs text-teal-200">Academic MVP · Demo data only</div><button @click="logout" class="mt-4 text-left text-sm">Sign out ↗</button></aside>
 <main class="min-w-0 flex-1 p-4 sm:p-7 max-w-7xl mx-auto w-full"><header class="flex flex-wrap gap-3 justify-between items-center"><div><p class="text-xs text-slate-500">JOTNO HEALTHCARE / {{section.toUpperCase()}}</p><h1 class="text-2xl sm:text-3xl font-bold mt-1">Hello, {{user?.name}}</h1><p class="text-sm text-slate-500 mt-1">{{roleLabel}} · Healthcare, when you need it.</p></div><div class="flex gap-2"><select v-model="section" class="field lg:hidden"><option v-for="x in sections" :key="x">{{x}}</option></select><button class="btn" @click="loadAll">Refresh</button></div></header>
 <p v-if="message" class="mt-5 rounded-xl bg-teal-50 text-teal-900 p-3 text-sm">{{message}}</p><p v-if="error" class="mt-5 rounded-xl bg-red-50 text-red-800 p-3 text-sm">{{error}}</p>
 <template v-if="section==='Overview'"><div class="grid sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-7"><div v-for="s in stats" :key="s.label" class="panel p-5"><p class="text-sm text-slate-500">{{s.label}}</p><p class="text-3xl font-bold mt-2">{{s.value}}</p></div></div><div class="grid xl:grid-cols-2 gap-5 mt-5"><div class="panel p-5"><h2 class="font-bold">Recent admission requests</h2><div v-for="a in admissions.slice(0,5)" :key="a.id" class="border-b py-3 text-sm"><b>{{a.patient?.user?.name||'Your request'}}</b><span class="float-right rounded-full bg-amber-50 px-2 py-1 text-amber-800">{{a.status}}</span><p class="text-slate-500 mt-1">{{a.reason}}</p></div><p v-if="!admissions.length" class="text-sm text-slate-500 mt-3">No admission requests yet.</p></div><div class="panel p-5"><h2 class="font-bold">Recent assessments</h2><div v-for="a in assessments" :key="a.id" class="border-b py-3 text-sm"><b>{{a.predicted_label||'Pending'}}</b><span class="float-right text-slate-500">{{a.doctor_status}}</span><p class="text-slate-500">{{a.department}} · {{a.created_at?.slice(0,10)}}</p></div><p v-if="!assessments.length" class="text-sm text-slate-500 mt-3">No AI assessments yet.</p></div></div></template>
 <section v-else-if="section==='Virtual Admission'" class="panel p-5 mt-6"><h2 class="text-lg font-bold">Virtual admission</h2><template v-if="user?.role==='patient'"><p class="text-sm text-slate-500 mt-1">Submit a request for review by the duty doctor.</p><form @submit.prevent="requestAdmission" class="mt-4 space-y-3"><textarea v-model="admission.reason" class="field" rows="3" placeholder="Reason for requesting home-care assessment" required></textarea><input v-model="admission.symptoms" class="field" placeholder="Symptoms (comma separated)"><button class="btn">Submit request</button></form></template><div v-for="a in admissions" :key="a.id" class="border rounded-xl p-4 mt-4"><div class="flex justify-between gap-2"><b>Request #{{a.id}} · {{a.patient?.user?.name||'My request'}}</b><span class="text-sm text-amber-700">{{a.status}}</span></div><p class="text-sm mt-2">{{a.reason}}</p><p v-if="a.review_note" class="text-sm text-slate-500">Doctor note: {{a.review_note}}</p><div v-if="['doctor','admin'].includes(user?.role)&&a.status==='pending'" class="flex gap-2 mt-3"><button class="btn" @click="reviewAdmission(a,'approved')">Approve</button><button class="btn bg-slate-600" @click="reviewAdmission(a,'needs_information')">Need info</button><button class="btn bg-red-700" @click="reviewAdmission(a,'rejected')">Reject</button></div></div></section>
 <section v-else-if="section==='Patients'" class="panel p-5 mt-6"><h2 class="font-bold text-lg">Patient directory</h2><div v-for="p in patients" :key="p.id" class="border-b py-3 flex flex-wrap justify-between gap-2"><div><b>{{p.user?.name}}</b><p class="text-xs text-slate-500">Patient ID: {{p.id}} · {{p.user?.email}}</p></div><button class="text-teal-700 text-sm" @click="selectedPatient=p;section='Monitoring'">Open record →</button></div><p v-if="!patients.length" class="text-sm text-slate-500 mt-3">No patient records available. Patients can register and submit admission requests.</p></section>
 <section v-else-if="section==='Monitoring'" class="panel p-5 mt-6"><h2 class="font-bold text-lg">Health observations</h2><label class="block text-sm mt-4">Patient</label><select v-model="patientId" class="field mt-1"><option value="">Select patient</option><option v-for="p in patients" :value="p.id" :key="p.id">{{p.user?.name}} (#{{p.id}})</option></select><form @submit.prevent="addObservation" class="grid sm:grid-cols-2 gap-3 mt-4"><input class="field" v-model="observation.temperature" type="number" step="0.1" placeholder="Temperature °C"><input class="field" v-model="observation.spo2" type="number" placeholder="SpO₂ %"><input class="field" v-model="observation.heart_rate" type="number" placeholder="Heart rate bpm"><input class="field" v-model="observation.systolic_bp" type="number" placeholder="Systolic BP"><input class="field" v-model="observation.diastolic_bp" type="number" placeholder="Diastolic BP"><input class="field" v-model="observation.notes" placeholder="Notes"><button class="btn sm:col-span-2">Save observation</button></form><canvas ref="observationCanvas" height="110" class="mt-5"></canvas><div v-for="o in observations" :key="o.id" class="border-b py-3 text-sm"><b>{{o.recorded_at||o.created_at}}</b><p class="text-slate-600">Temp {{o.temperature??'—'}}°C · SpO₂ {{o.spo2??'—'}}% · Pulse {{o.heart_rate??'—'}} · BP {{o.systolic_bp??'—'}}/{{o.diastolic_bp??'—'}}</p></div><p class="text-xs text-slate-500 mt-3">Entered observations and threshold flags are educational records, not a clinical risk score.</p></section>
 <section v-else-if="section==='AI Assessment'" class="panel p-5 mt-6"><h2 class="font-bold text-lg">Preliminary symptom assessment</h2><p class="text-sm text-slate-500 mt-1">Dataset-based output only. A doctor must review it; it is not a diagnosis.</p><div class="rounded-xl bg-slate-50 p-3 mt-3 text-xs text-slate-600"><b>English:</b> This is a preliminary dataset suggestion, not a diagnosis or treatment recommendation. A qualified doctor must review it.<br><b>বাংলা:</b> এটি ডেটাসেটভিত্তিক প্রাথমিক পরামর্শ মাত্র; রোগ নির্ণয় বা চিকিৎসার নির্দেশনা নয়। যোগ্য চিকিৎসকের পর্যালোচনা আবশ্যক।</div><label class="block text-sm mt-4">Patient</label><select v-model="patientId" class="field mt-1"><option value="">Select patient</option><option v-for="p in patients" :value="p.id" :key="p.id">{{p.user?.name}} (#{{p.id}})</option></select><form @submit.prevent="predict" class="mt-3"><textarea v-model="symptomText" class="field" rows="3" placeholder="Enter symptom features separated by commas (use model feature names)" required></textarea><button class="btn mt-3">Run preliminary model</button></form><div v-for="a in assessments" :key="a.id" class="border rounded-xl p-3 mt-3 text-sm"><b>{{a.predicted_label}}</b> · {{a.department}}<p class="text-slate-500">Review: {{a.doctor_status}}</p><div v-if="['doctor','admin','specialist'].includes(user?.role)&&a.doctor_status==='pending'" class="flex gap-2 mt-2"><button class="btn" @click="reviewAssessment(a,'accepted')">Accept</button><button class="btn bg-slate-600" @click="reviewAssessment(a,'needs_followup')">Follow up</button><button class="btn bg-red-700" @click="reviewAssessment(a,'rejected')">Reject</button></div></div></section>
 <section v-else-if="section==='Care Plans'" class="panel p-5 mt-6"><h2 class="font-bold text-lg">Care plans and reminders</h2><select v-model="patientId" class="field mt-4"><option value="">Select patient</option><option v-for="p in patients" :value="p.id" :key="p.id">{{p.user?.name}} (#{{p.id}})</option></select><form v-if="['doctor','admin'].includes(user?.role)" @submit.prevent="addCarePlan" class="space-y-3 mt-3"><input v-model="plan.title" class="field" placeholder="Plan title" required><textarea v-model="plan.instructions" class="field" placeholder="Doctor-approved instructions" required></textarea><input v-model="plan.reminder_at" type="datetime-local" class="field"><button class="btn">Create care plan</button></form><div v-for="p in carePlans" :key="p.id" class="border-b py-3"><b>{{p.title}}</b><p class="text-sm">{{p.instructions}}</p><p class="text-xs text-slate-500">Reminder: {{p.reminder_at||'Not set'}}</p></div></section>
 <section v-else-if="section==='Referrals'" class="panel p-5 mt-6"><h2 class="font-bold text-lg">Specialist referrals</h2><form v-if="['doctor','admin'].includes(user?.role)" @submit.prevent="createReferral" class="grid sm:grid-cols-2 gap-3 mt-4"><select v-model="referral.patient_id" class="field"><option value="">Select patient</option><option v-for="p in patients" :key="p.id" :value="p.id">{{p.user?.name}}</option></select><select v-model="referral.specialist_id" class="field"><option value="">Select specialist account</option><option v-for="s in specialists" :key="s.id" :value="s.id">{{s.name}}</option></select><input v-model="referral.department" class="field" placeholder="Department"><input v-model="referral.reason" class="field" placeholder="Referral reason"><button class="btn sm:col-span-2">Create referral</button></form><div v-for="r in referrals" :key="r.id" class="border-b py-3 text-sm"><b>{{r.department}}</b> · {{r.status}}<p>{{r.reason}}</p><p v-if="r.specialist_note" class="text-slate-500">{{r.specialist_note}}</p></div><p v-if="!referrals.length" class="text-sm text-slate-500 mt-3">No referrals available.</p></section>
 <section v-else-if="section==='Consultations'" class="panel p-5 mt-6"><h2 class="font-bold text-lg">Video consultation schedule</h2><form v-if="['doctor','admin'].includes(user?.role)" @submit.prevent="createConsultation" class="grid sm:grid-cols-2 gap-3 mt-4"><select v-model="consultation.patient_id" class="field"><option value="">Select patient</option><option v-for="p in patients" :key="p.id" :value="p.id">{{p.user?.name}}</option></select><input v-model="consultation.scheduled_at" type="datetime-local" class="field"><input v-model="consultation.meeting_url" class="field sm:col-span-2" placeholder="Meeting URL (optional)"><button class="btn sm:col-span-2">Schedule consultation</button></form><p class="text-sm text-slate-500 mt-1">This stores appointment/session details. Add a meeting URL from your approved video provider.</p><div v-for="c in consultations" :key="c.id" class="border-b py-3 text-sm"><b>{{c.scheduled_at}}</b> · {{c.status}}<p><a v-if="c.meeting_url" :href="c.meeting_url" target="_blank" class="text-teal-700">Open meeting</a></p></div></section>
 <section v-else-if="section==='Reports'" class="panel p-5 mt-6"><h2 class="font-bold text-lg">Medical reports</h2><form @submit.prevent="uploadReport" class="mt-4 space-y-3"><select v-model="patientId" class="field"><option value="">Select patient</option><option v-for="p in patients" :key="p.id" :value="p.id">{{p.user?.name}}</option></select><input type="file" ref="reportFile" accept=".pdf,.jpg,.jpeg,.png" class="field" required><input v-model="reportDescription" class="field" placeholder="Description"><button class="btn">Upload report (max 5 MB)</button></form><div v-for="r in reports" :key="r.id" class="border-b py-2 text-sm">{{r.original_name}} · {{r.description}}</div></section>
 <section v-else-if="section==='Notifications'" class="panel p-5 mt-6"><h2 class="font-bold text-lg">Notifications</h2><div v-for="n in notifications" :key="n.id" class="border-b py-3"><b>{{n.title}}</b><p class="text-sm text-slate-600">{{n.body}}</p><button v-if="!n.read_at" class="text-xs text-teal-700 mt-1" @click="readNotification(n)">Mark as read</button></div></section>
 <section v-else-if="section==='Caregiver Access'" class="panel p-5 mt-6"><h2 class="font-bold text-lg">Caregiver access</h2><form v-if="user?.role==='caregiver'" @submit.prevent="requestCaregiver" class="flex gap-2 mt-3"><input v-model="caregiverPatientId" class="field" placeholder="Patient ID" required><button class="btn">Request access</button></form><div v-for="a in caregiverRequests" :key="a.id" class="border-b py-3 text-sm"><b>{{a.caregiver?.name}}</b> requests access to {{a.patient?.user?.name}} · {{a.status}}<div v-if="['doctor','admin'].includes(user?.role)&&a.status==='pending'" class="flex gap-2 mt-2"><button class="btn" @click="reviewCaregiver(a,'approved')">Approve</button><button class="btn bg-red-700" @click="reviewCaregiver(a,'rejected')">Reject</button></div></div><div v-for="p in caregiverPatients" :key="p.id" class="py-2">Authorized patient: {{p.user?.name}} (ID {{p.id}})</div></section>
 <footer class="text-xs text-slate-500 mt-8">Academic prototype only. Not for real patient care, diagnosis, treatment, or emergencies. AI outputs require qualified doctor review.</footer>
 </main></div>
</template>
<script setup>
import{ref,computed,onMounted,watch,nextTick,onBeforeUnmount}from'vue';import{Chart,registerables}from'chart.js';Chart.register(...registerables);import{useRouter}from'vue-router';import api from'../services/api';
let observationChart=null;const observationCanvas=ref(null),reportFile=ref(null),reportDescription=ref(''),reports=ref([]),specialists=ref([]),referral=ref({patient_id:'',specialist_id:'',department:'',reason:''}),consultation=ref({patient_id:'',scheduled_at:'',meeting_url:''});const router=useRouter(),user=ref(JSON.parse(localStorage.getItem('jh_user')||'null')),section=ref('Overview'),message=ref(''),error=ref(''),dashboard=ref({}),patients=ref([]),admissions=ref([]),assessments=ref([]),observations=ref([]),carePlans=ref([]),referrals=ref([]),consultations=ref([]),notifications=ref([]),caregiverRequests=ref([]),caregiverPatients=ref([]),selectedPatient=ref(null),patientId=ref(''),symptomText=ref(''),caregiverPatientId=ref(''),admission=ref({reason:'',symptoms:''}),observation=ref({temperature:'',spo2:'',heart_rate:'',systolic_bp:'',diastolic_bp:'',notes:''}),plan=ref({title:'',instructions:'',reminder_at:''});
const sections=computed(()=>{let a=['Overview','Virtual Admission','Patients','Monitoring','AI Assessment','Care Plans','Reports','Referrals','Consultations','Notifications'];if(['doctor','admin'].includes(user.value?.role))a.push('Caregiver Access');if(user.value?.role==='caregiver')a.push('Caregiver Access');return a}),roleLabel=computed(()=>({patient:'Patient',caregiver:'Caregiver',doctor:'Duty Doctor',specialist:'Specialist',admin:'Administrator'}[user.value?.role]||'Workspace')),stats=computed(()=>[{label:'Patient records',value:dashboard.value.patients??0},{label:'Observations today',value:dashboard.value.observations_today??0},{label:'Pending doctor reviews',value:dashboard.value.pending_reviews??0},{label:'Review flags (not risk score)',value:dashboard.value.rule_flags??0}]);
async function safe(p){try{return(await p).data}catch(e){throw e}}async function loadAll(){error.value='';try{const d=await safe(api.get('/dashboard'));dashboard.value=d;const jobs=[api.get('/patients'),api.get('/admissions'),api.get('/assessments'),api.get('/referrals'),api.get('/consultations'),api.get('/notifications')];const vals=await Promise.all(jobs.map(x=>safe(x).catch(()=>[])));patients.value=vals[0].data||vals[0]||[];admissions.value=vals[1]||[];assessments.value=vals[2].data||vals[2]||[];referrals.value=vals[3]||[];consultations.value=vals[4]||[];notifications.value=vals[5]||[];if(user.value?.role==='caregiver'){caregiverPatients.value=await safe(api.get('/caregiver/patients')).catch(()=>[])}if(['doctor','admin'].includes(user.value?.role)){caregiverRequests.value=await safe(api.get('/caregiver-access/requests')).catch(()=>[])}if(user.value?.role==='patient'&&patients.value.length)patientId.value=patients.value[0].id;else if(!patientId.value&&patients.value.length)patientId.value=patients.value[0].id;if(['doctor','admin'].includes(user.value?.role)){specialists.value=await safe(api.get('/users?role=specialist')).catch(()=>[])}}catch(e){error.value=e.response?.data?.message||'Could not load data. Check Laravel API, database and login.'}}
async function requestAdmission(){try{await safe(api.post('/admissions',{reason:admission.value.reason,symptoms:admission.value.symptoms.split(',').map(x=>x.trim()).filter(Boolean)}));message.value='Admission request submitted for doctor review.';admission.value={reason:'',symptoms:''};await loadAll()}catch(e){error.value=e.response?.data?.message||'Could not submit request.'}}
async function reviewAdmission(a,status){try{await safe(api.patch(`/admissions/${a.id}/review`,{status}));message.value='Admission request updated.';await loadAll()}catch(e){error.value=e.response?.data?.message||'Could not update request.'}}
async function addObservation(){try{const data={};for(const k in observation.value)if(observation.value[k]!=='')data[k]=['notes'].includes(k)?observation.value[k]:Number(observation.value[k]);await safe(api.post(`/patients/${patientId.value}/observations`,data));message.value='Observation saved.';observations.value=await safe(api.get(`/patients/${patientId.value}/observations`));}catch(e){error.value=e.response?.data?.message||'Could not save observation.'}}
async function predict(){try{await safe(api.post('/predict',{patient_id:Number(patientId.value),symptoms:symptomText.value.split(',').map(x=>x.trim()).filter(Boolean)}));message.value='Preliminary assessment created and sent for doctor review.';assessments.value=(await safe(api.get('/assessments'))).data||[];}catch(e){error.value=e.response?.data?.unknown_symptoms?`Unknown model features: ${e.response.data.unknown_symptoms.join(', ')}`:(e.response?.data?.message||'ML service unavailable. Start Flask service.')}}
async function reviewAssessment(a,status){try{await safe(api.patch(`/assessments/${a.id}/review`,{doctor_status:status,doctor_note:'Reviewed in academic MVP'}));message.value='Assessment review saved.';await loadAll()}catch(e){error.value=e.response?.data?.message||'Review failed.'}}
async function addCarePlan(){try{await safe(api.post(`/patients/${patientId.value}/care-plans`,{...plan.value,reminder_at:plan.value.reminder_at||null}));message.value='Care plan created.';plan.value={title:'',instructions:'',reminder_at:''};carePlans.value=await safe(api.get(`/patients/${patientId.value}/care-plans`))}catch(e){error.value=e.response?.data?.message||'Could not create care plan.'}}
async function uploadReport(){try{const fd=new FormData();fd.append('report',reportFile.value.files[0]);fd.append('description',reportDescription.value);await safe(api.post(`/patients/${patientId.value}/reports`,fd,{headers:{'Content-Type':'multipart/form-data'}}));message.value='Report uploaded.';reportFile.value.value='';reportDescription.value=''}catch(e){error.value=e.response?.data?.message||'Upload failed.'}}
async function createReferral(){try{const d={...referral.value};const pid=d.patient_id;delete d.patient_id;await safe(api.post(`/patients/${pid}/referrals`,d));message.value='Referral created.';referral.value={patient_id:'',specialist_id:'',department:'',reason:''};await loadAll()}catch(e){error.value=e.response?.data?.message||'Referral failed.'}}
async function createConsultation(){try{const d={...consultation.value};const pid=d.patient_id;delete d.patient_id;await safe(api.post(`/patients/${pid}/consultations`,d));message.value='Consultation scheduled.';consultation.value={patient_id:'',scheduled_at:'',meeting_url:''};await loadAll()}catch(e){error.value=e.response?.data?.message||'Scheduling failed.'}}
async function readNotification(n){await safe(api.patch(`/notifications/${n.id}/read`));n.read_at=new Date().toISOString()}
async function requestCaregiver(){try{await safe(api.post('/caregiver-access',{patient_id:Number(caregiverPatientId.value)}));message.value='Access request sent to care team.'}catch(e){error.value=e.response?.data?.message||'Request failed.'}}
async function reviewCaregiver(a,status){await safe(api.patch(`/caregiver-access/${a.id}`,{status}));await loadAll()}
function logout(){localStorage.removeItem('jh_token');localStorage.removeItem('jh_user');router.push('/login')}
watch([section,patientId],async()=>{if(patientId.value&&['Monitoring','Care Plans','Reports'].includes(section.value)){try{if(section.value==='Monitoring'){observations.value=await safe(api.get(`/patients/${patientId.value}/observations`));await nextTick();drawChart()}if(section.value==='Care Plans')carePlans.value=await safe(api.get(`/patients/${patientId.value}/care-plans`));if(section.value==='Reports'){const d=await safe(api.get(`/patients/${patientId.value}`));reports.value=d.reports||[]}}catch(e){error.value=e.response?.data?.message||'Could not load patient details.'}}});function drawChart(){if(!observationCanvas.value)return;if(observationChart)observationChart.destroy();const rows=[...observations.value].reverse();observationChart=new Chart(observationCanvas.value,{type:'line',data:{labels:rows.map(x=>(x.recorded_at||x.created_at||'').slice(0,10)),datasets:[{label:'Temperature °C',data:rows.map(x=>x.temperature),spanGaps:true},{label:'SpO₂ %',data:rows.map(x=>x.spo2),spanGaps:true},{label:'Heart rate bpm',data:rows.map(x=>x.heart_rate),spanGaps:true}]},options:{responsive:true,plugins:{legend:{position:'bottom'}}}})}onBeforeUnmount(()=>observationChart?.destroy());onMounted(loadAll);
</script>
